def trigger_gdpr_export_job(request, export_id):
    export_job = get_object_or_404(DataExportRequest, id=export_id, user=request.user)
    generate_gdpr_archive_task.apply_async(args=[export_job.id])
    return JsonResponse({'status': 'processing', 'job_id': export_job.id})
